#include <iostream>
enum class OpenMode : unsigned int {
    In = 1 << 0,
    Out = 1 << 1,
    Append = 1 << 2
};

int main() {
    // Combine multiple open modes using bitwise OR
    unsigned int mode = static_cast<unsigned int>(OpenMode::In) | static_cast<unsigned int>(OpenMode::Out);
    // Check if a specific mode is set
    if (mode & static_cast<unsigned int>(OpenMode::In)) {
        std::cout << "Input mode is enabled." << std::endl;
    }
    if (mode & static_cast<unsigned int>(OpenMode::Out)) {
        std::cout << "Output mode is enabled." << std::endl;
    }
    return 0;
}
